def has_short_cycle(adj, n, max_len=6):
    """Check if there's a cycle of length <= max_len"""
    # BFS from each vertex to find shortest cycle
    for start in range(n):
        # BFS
        dist = {start: 0}
        parent = {start: None}
        queue = [start]
        qi = 0
        while qi < len(queue):
            u = queue[qi]
            qi += 1
            if dist[u] >= max_len:
                continue
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent.get(u) and dist[v] >= dist[u]:
                    # Found a cycle
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len <= max_len:
                        return True
    return False

