def simulated_annealing(n, iterations=200000):
    random.seed(42)

    # Start with a random graph
    edges = set()
    adj = {i: set() for i in range(n)}

    # Create initial edges
    stubs = []
    for v in range(n):
        for _ in range(3):
            stubs.append(v)

    if len(stubs) % 2 == 1:
        stubs.append(random.randint(0, n-1))

    random.shuffle(stubs)
    for i in range(0, len(stubs)-1, 2):
        u, v = stubs[i], stubs[i+1]
        if u != v and (min(u,v), max(u,v)) not in edges:
            edges.add((min(u,v), max(u,v)))
            adj[u].add(v)
            adj[v].add(u)

    for u in range(n):
        for v in range(u+1, n):
            if len(adj[u]) < 7 and len(adj[v]) < 7 and (u,v) not in edges:
                if random.random() < 0.3:
                    edges.add((u,v))
                    adj[u].add(v)
                    adj[v].add(u)

    current_edges = edges.copy()
    current_adj = {v: set(adj[v]) for v in range(n)}
    current_score = score(current_adj, n)

    best_edges = current_edges.copy()
    best_adj = {v: set(current_adj[v]) for v in range(n)}
    best_score = current_score

    print(f"Initial score: {best_score}")

    for it in range(iterations):
        temp = max(0.01, 1.0 - it / iterations)

        # Try a random move
        move_type = random.choice(['add', 'remove', 'swap'])

        if move_type == 'add':
            u = random.randint(0, n-1)
            v = random.randint(0, n-1)
            if u >= v:
                u, v = v, u
            if u == v or (u,v) in current_edges or len(current_adj[u]) >= 7 or len(current_adj[v]) >= 7:
                continue

            current_edges.add((u,v))
            current_adj[u].add(v)
            current_adj[v].add(u)
            new_score = score(current_adj, n)

            delta = new_score - current_score
            if delta < 0 or random.random() < math.exp(-delta / (temp * 100)):
                current_score = new_score
                if current_score < best_score:
                    best_score = current_score
                    best_edges = current_edges.copy()
                    best_adj = {v: set(current_adj[v]) for v in range(n)}
            else:
                current_edges.remove((u,v))
                current_adj[u].remove(v)
                current_adj[v].remove(u)

        elif move_type == 'remove':
            if not current_edges:
                continue
            e = random.choice(list(current_edges))
            u, v = e
            current_edges.remove(e)
            current_adj[u].remove(v)
            current_adj[v].remove(u)
            new_score = score(current_adj, n)

            delta = new_score - current_score
            if delta < 0 or random.random() < math.exp(-delta / (temp * 100)):
                current_score = new_score
                if current_score < best_score:
                    best_score = current_score
                    best_edges = current_edges.copy()
                    best_adj = {v: set(current_adj[v]) for v in range(n)}
            else:
                current_edges.add(e)
                current_adj[u].add(v)
                current_adj[v].add(u)

        elif move_type == 'swap':
            if not current_edges:
                continue
            e = random.choice(list(current_edges))
            u, v = e
            current_edges.remove(e)
            current_adj[u].remove(v)
            current_adj[v].remove(u)

            u2 = random.randint(0, n-1)
            v2 = random.randint(0, n-1)
            if u2 >= v2:
                u2, v2 = v2, u2
            if u2 == v2 or (u2,v2) in current_edges or len(current_adj[u2]) >= 7 or len(current_adj[v2]) >= 7:
                current_edges.add(e)
                current_adj[u].add(v)
                current_adj[v].add(u)
                continue

            current_edges.add((u2,v2))
            current_adj[u2].add(v2)
            current_adj[v2].add(u2)
            new_score = score(current_adj, n)

            delta = new_score - current_score
            if delta < 0 or random.random() < math.exp(-delta / (temp * 100)):
                current_score = new_score
                if current_score < best_score:
                    best_score = current_score
                    best_edges = current_edges.copy()
                    best_adj = {v: set(current_adj[v]) for v in range(n)}
            else:
                current_edges.remove((u2,v2))
                current_adj[u2].remove(v2)
                current_adj[v2].remove(u2)
